TEST_F(DictionaryTest, CorruptCompressedDataFailsWithoutClaimingAMiss) {
  const std::string folder = provision("zipped", "ZippedCorrupt");
  Dictionary dict;
  ASSERT_NO_FATAL_FAILURE(openIndexed(dict, folder));

  // Truncate the compressed data, leaving the header and its chunk table intact.
  // The last headword's bytes live in the final chunk, so its compressed data is
  // certainly gone. The index still says the entry is there, so a failure here
  // must be named as a failure, not reported as "not found".
  const fs::path dz = kDictRoot / folder / "zipped.dict.dz";
  std::string blob = readWholeFile(dz);
  blob.resize(blob.size() / 2);
  writeWholeFile(dz, blob);

  const std::string& lastWord = plainEntries.back().word;
  std::string definition;
  std::string headword;
  Dictionary::LookupResult result = Dictionary::LookupResult::Found;
  EXPECT_FALSE(dict.lookup(lastWord.c_str(), definition, headword, &result));
  EXPECT_TRUE(result == Dictionary::LookupResult::ReadError || result == Dictionary::LookupResult::Decompress)
      << "unexpected result " << static_cast<int>(result);
}

// --- index scanning edge cases ---------------------------------------------

TEST_F(DictionaryTest, OverlongHeadwordDoesNotDesynchroniseTheScan) {
  // A headword longer than the reader's word buffer is truncated, but the entry
  // after it must still be found: the scan has to skip the rest of the word and
  // its 8 suffix bytes exactly.
  const std::string giant(600, 'm');
  const std::string tail = "zebra";
  const std::string body = "the striped one";

  std::string idx;
  const auto appendEntry = [&idx](const std::string& word, uint32_t offset, uint32_t size) {
    idx += word;
    idx += '\0';
    const uint8_t suffix[8] = {static_cast<uint8_t>(offset >> 24), static_cast<uint8_t>(offset >> 16),
                               static_cast<uint8_t>(offset >> 8),  static_cast<uint8_t>(offset),
                               static_cast<uint8_t>(size >> 24),   static_cast<uint8_t>(size >> 16),
                               static_cast<uint8_t>(size >> 8),    static_cast<uint8_t>(size)};
    idx.append(reinterpret_cast<const char*>(suffix), sizeof(suffix));
  };
  appendEntry(giant, 0, 5);
  appendEntry(tail, 5, static_cast<uint32_t>(body.size()));

  fs::remove_all(kDictRoot / "Overlong");
  writeWholeFile(kDictRoot / "Overlong" / "big.idx", idx);
  writeWholeFile(kDictRoot / "Overlong" / "big.dict", "GIANT" + body);
  writeWholeFile(kDictRoot / "Overlong" / "big.ifo", "StarDict's dict ifo file\nsametypesequence=m\n");

  Dictionary dict;
  ASSERT_NO_FATAL_FAILURE(openIndexed(dict, "Overlong"));

  std::string definition;
  std::string headword;
  ASSERT_TRUE(dict.lookup(tail.c_str(), definition, headword));
  EXPECT_EQ(headword, tail);
  EXPECT_EQ(definition, body);
}

