// --- prefix search (runs of CJK text) ----------------------------------------

using HitList = std::vector<std::pair<std::string, int>>;

// Each hit's headword and the run bytes it covers, longest first.
HitList hitsOf(const DictPrefixMatch& match) {
  HitList hits;
  for (uint8_t i = 0; i < match.count; i++) hits.emplace_back(match.hits[i].headword, match.hits[i].runBytes);
  return hits;
}

std::string cp(uint32_t codepoint) {
  std::string out;
  utf8AppendCodepoint(out, codepoint);
  return out;
}

std::string definitionAt(Dictionary& dict, const DictLocation& location) {
  std::string definition;
  EXPECT_TRUE(dict.readResolved(location, definition));
  return definition;
}

bool abortAlways() { return true; }

const std::vector<HeadwordSpec> kBasic = {{"大", "big"},   {"大学", "university"}, {"大学生", "student"},
                                          {"学", "study"}, {"学生", "pupil"},      {"生活", "life"}};

// `count` ASCII headwords "a000", "a001", ...: they sort before every CJK headword, so they push
// the ones after them across the sidecar's 256-entry sample boundary.
std::vector<HeadwordSpec> asciiFillers(int count) {
  std::vector<HeadwordSpec> headwords;
  for (int i = 0; i < count; i++) {
    char word[16];
    snprintf(word, sizeof(word), "a%03d", i);
    headwords.push_back({word, "filler"});
  }
  return headwords;
}

// `leading` fillers, 大 and 大学, then `trailing` headwords 大学 + one more ideograph: with them, the
// descent for 大学生活 lands in a window past both matches.
std::vector<HeadwordSpec> windowLayout(int leading, int trailing) {
  std::vector<HeadwordSpec> headwords = asciiFillers(leading);
  headwords.push_back({"大", "big"});
  headwords.push_back({"大学", "university"});
  for (int i = 0; i < trailing; i++) headwords.push_back({"大学" + cp(0x4E00 + i), "filler"});
  return headwords;
}

TEST_F(DictionaryTest, PrefixSearchFindsTheLongestHeadwordAndTwoShorter) {
  ASSERT_NO_FATAL_FAILURE(writeDictionary("PrefixBasic", kBasic));
  Dictionary dict;
  ASSERT_NO_FATAL_FAILURE(openIndexed(dict, "PrefixBasic"));

  DictPrefixMatch m;
  Dictionary::LookupResult r = Dictionary::LookupResult::NotFound;
  ASSERT_TRUE(dict.resolvePrefixes("大学生活", m, &r));
  EXPECT_EQ(r, Dictionary::LookupResult::Found);
  EXPECT_EQ(hitsOf(m), (HitList{{"大学生", 9}, {"大学", 6}, {"大", 3}}));
  EXPECT_EQ(definitionAt(dict, m.hits[0].location), "student");
  EXPECT_EQ(m.probes, 1);
  EXPECT_GT(m.reads, 0);
  EXPECT_FALSE(m.aborted);
}

